function Field({label,value,onChange,error,hint,dir='rtl',type='text',placeholder,readOnly=false}:{label:string;value:string;onChange:(s:string)=>void;error?:string;hint?:string;dir?:'rtl'|'ltr';type?:string;placeholder?:string;readOnly?:boolean}){const k=useKeyboard();const id='input-'+label.replace(/\s/g,'-');return <div className={'form-field '+(error?'invalid':'')}><label htmlFor={id}>{label}</label><KeyboardInput id={id} value={value} onChange={e=>onChange(e.target.value)} onBlur={()=>k.hide()} type={type} inputMode={type==='tel'?'tel':type==='number'?'decimal':undefined} dir={dir} placeholder={placeholder} readOnly={readOnly} aria-invalid={!!error} aria-describedby={id+'-hint'} autoComplete="off"/><span id={id+'-hint'} className={error?'field-error':'field-hint'}>{error||hint}</span></div>}
function Chips({label,options,values,onChange,none,disabled=false}:{label:string;options:string[];values:string[];onChange:(a:string[])=>void;none?:string;disabled?:boolean}){return <fieldset className="chips-field" disabled={disabled}><legend>{label}</legend><div className="chip-grid">{options.map(v=><button key={v} className={'chip '+(values.includes(v)?'selected':'')} aria-pressed={values.includes(v)} onClick={()=>onChange(v===none?(values.includes(v)?[]:[v]):values.includes(v)?values.filter(x=>x!==v):[...values.filter(x=>x!==none),v])}>{values.includes(v)&&<Check size={14}/>}<span>{v}</span></button>)}</div></fieldset>}

