 const current=restaurants[index];const completed=Math.min(members.length,otherComplete+(ownComplete?1:0));const readyCount=ready.filter(Boolean).length;const allAnswered=answers.every(a=>a!==null);const likes=answers.filter(a=>a==='like').length;
 const nav=(next:Screen)=>{keyboard.hide();setSheet(null);setMessage('');setErrors({});setScreen(next);keepAppFocus();setVariant('default');setGalleryOpen(false);const u=new URL(window.location.href);u.searchParams.set('screen',next);u.searchParams.delete('state');window.history.replaceState(null,'',u);};
