 const saveAnswer=async(answer:Answer)=>{if(pending.current||!answer)return;if(settled){nav(result.winner===null?'empty':'result');return;}pending.current=true;setBusy(true);setSaveError(null);await pause(300);if(variant==='save-error'){setSaveError(answer);setVariant('default');pending.current=false;setBusy(false);return;}const next=[...answers];next[index]=answer;setHistory(h=>[...h,{i:index,previous:answers[index]}]);setAnswers(next);setOwnComplete(false);if(editing){setEditing(false);nav('review');}else{const after=next.findIndex((a,i)=>i>index&&a===null);const any=next.findIndex(a=>a===null);if(after>=0)setIndex(after);else if(any>=0)setIndex(any);else nav('review');}pending.current=false;setBusy(false);};
