 const submitAccount=()=>{const e:Record<string,string>={};const normalized=digits(phone).replace(/[\s()-]/g,'');if(!login&&!name.trim())e.name='اكتب اسمك الذي سيظهر للمشاركين.';if(!/^(05\d{8}|\+9665\d{8})$/.test(normalized))e.phone='أدخل رقمًا سعوديًا مثل 05xxxxxxxx.';setErrors(e);if(Object.keys(e).length)return;request(()=>{setPhone(normalized);setOtp('');setOtpWait(30);nav('verify');});};
